using System.Text.Json.Nodes;
using Gaius.Office;
using UglyToad.PdfPig.DocumentLayoutAnalysis.TextExtractor;

int checks = 0;
void Check(bool condition, string message) { if (!condition) throw new Exception(message); checks++; }
WinRT.ComWrappersSupport.InitializeComWrappers();
var text = "Colour Ω नमस्ते 😀";
var delta = RichTextInterop.HtmlToDelta("<p><strong style='color:#c43e1c'>" + text + "</strong></p><table><tr><td>Revenue</td><td>120</td></tr></table>");
Check(delta[0]?["attributes"]?["color"]?.ToString() == "#c43e1c", "HTML text color lost");
Check(delta[0]?["attributes"]?["bold"]?.GetValue<bool>() == true, "HTML bold lost");
var rtf = RichTextInterop.ToRtf(delta);
Check(rtf.Contains("\\red196\\green62\\blue28"), "RTF color table missing");
var html = RtfPipe.Rtf.ToHtml(rtf);
var familyHtml = RtfPipe.Rtf.ToHtml(RichTextInterop.ToRtf(RichTextInterop.HtmlToDelta("<p style='font-family:Georgia'>Typeface check</p>")));
Check(familyHtml.Contains("Georgia", StringComparison.OrdinalIgnoreCase), "Document font family failed native rich-text round trip");
var headingHtml = RtfPipe.Rtf.ToHtml(RichTextInterop.ToRtf(RichTextInterop.HtmlToDelta("<h1>Template heading</h1>")));
Check(headingHtml.Contains("24pt") || headingHtml.Contains("32px"), "Template headings lost their visible font size");
Check(html.Contains(text), "Unicode text failed RTF round trip");
Check(html.Contains("<table") && html.Contains("Revenue"), "RTF table failed round trip");
Check(html.Contains("#C43E1C", StringComparison.OrdinalIgnoreCase) || html.Contains("rgb(196,62,28)") || html.Contains("rgb(196, 62, 28)"), "RTF color failed round trip");
var png = File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory, "fixtures", "gradient.png"));
var imageDelta = new JsonArray(new JsonObject { ["insert"] = new JsonObject { ["image"] = "data:image/png;base64," + Convert.ToBase64String(png) } });
Check(RtfPipe.Rtf.ToHtml(RichTextInterop.ToRtf(imageDelta)).Contains("data:image/png;base64,"), "Embedded image lost");
var workbook = OfficeFile.Create("spreadsheet");
workbook.Data["worksheets"] = new JsonArray(new JsonObject { ["name"] = "One", ["cells"] = new JsonObject { ["A1"] = "first" }, ["rows"] = 100, ["columns"] = 26 }, new JsonObject { ["name"] = "Two", ["cells"] = new JsonObject { ["A1"] = "second" }, ["rows"] = 100, ["columns"] = 26 });
workbook.Data["activeSheet"] = 1;
var copy = workbook.Copy();
Check(copy.Data["sheet"]?["cells"]?["A1"]?.ToString() == "second", "Active worksheet export alias is stale");
copy.Sheet["cells"]!["A1"] = "changed";
Check(workbook.Sheet["cells"]?["A1"]?.ToString() == "second", "Workbook copy mutates source");
var sheet = new JsonObject { ["rows"] = 100, ["columns"] = 26, ["cells"] = new JsonObject { ["A1"] = "Label", ["B1"] = "Value", ["A2"] = "B", ["B2"] = "12", ["A3"] = "A", ["B3"] = "4" }, ["styles"] = new JsonObject { ["A2"] = new JsonObject { ["bold"] = true } } };
SheetData.Sort(sheet, "A2:B3", "A2", false);
Check(sheet["cells"]?["A2"]?.ToString() == "A" && sheet["cells"]?["B2"]?.ToString() == "4", "Sort broke row records");
Check(sheet["styles"]?["A3"]?["bold"]?.GetValue<bool>() == true, "Sort detached formatting");
sheet["cells"]!["B4"] = "=SUM(B2:B3)";
Check(SheetData.Value(sheet, "B4") == "16", "Native formula calculation failed");
bool rejected = false; try { SheetData.Sort(sheet, "A2:B4", "A2", false); } catch (InvalidOperationException) { rejected = true; }
Check(rejected, "Sort silently moved formula references");
var encoded = await BitmapTools.Target(png, 5000);
Check(encoded.Bytes[0] == 255 && encoded.Bytes[1] == 216 && encoded.Bytes.Length <= 5000, "Image target compression did not produce the requested JPEG");
using (var pdf = UglyToad.PdfPig.PdfDocument.Open(Path.Combine(AppContext.BaseDirectory, "fixtures", "selection.pdf"))) Check(ContentOrderTextExtractor.GetText(pdf.GetPage(1)).Contains("Alpha budget 120"), "PDF text extraction failed");
var document = OfficeFile.Create("document"); document.Content["delta"] = delta.DeepClone(); ((JsonArray)document.Content["delta"]!).Add(imageDelta[0]!.DeepClone());
var docx = OfficeInterchange.Export(document); var reopenedDoc = OfficeInterchange.Import(docx, ".docx");
Check(reopenedDoc.Content["html"]!.ToString().Contains(text), "Native DOCX lost Unicode text");
Check(reopenedDoc.Content["html"]!.ToString().Contains("<table") && reopenedDoc.Content["html"]!.ToString().Contains("data:image/png;base64,"), "Native DOCX lost images or tables");
Check(reopenedDoc.Content["html"]!.ToString().Contains("#C43E1C", StringComparison.OrdinalIgnoreCase), "Native DOCX lost color");
workbook.Sheet["cells"]!["B1"] = "=SUM(1,2)"; workbook.Sheet["styles"] = new JsonObject { ["A1"] = new JsonObject { ["bold"] = true, ["background"] = "#dce8fa", ["format"] = "currency" } };
var xlsx = OfficeInterchange.Export(workbook); var reopenedBook = OfficeInterchange.Import(xlsx, ".xlsx"); reopenedBook.Data["activeSheet"] = 1;
Check(reopenedBook.Sheet["cells"]?["B1"]?.ToString() == "=SUM(1,2)", "Native XLSX lost formulas");
Check(reopenedBook.Sheet["styles"]?["A1"]?["bold"]?.GetValue<bool>() == true && string.Equals(reopenedBook.Sheet["styles"]?["A1"]?["background"]?.ToString(), "#dce8fa", StringComparison.OrdinalIgnoreCase), "Native XLSX lost formatting");
var slides = OfficeFile.Create("presentation"); slides.Slides[0]!["notes"] = "Speaker notes"; slides.Slides[0]!["objects"] = new JsonArray(new JsonObject { ["id"] = "shape", ["kind"] = "ellipse", ["x"] = 10, ["y"] = 50, ["width"] = 30, ["height"] = 20, ["color"] = "#107c41" }, new JsonObject { ["id"] = "picture", ["kind"] = "image", ["x"] = 50, ["y"] = 50, ["width"] = 30, ["height"] = 20, ["color"] = "#185abd", ["dataUrl"] = "data:image/png;base64," + Convert.ToBase64String(png) });
var pptx = OfficeInterchange.Export(slides); var reopenedSlides = OfficeInterchange.Import(pptx, ".pptx");
Check(reopenedSlides.Slides[0]?["objects"]?.AsArray().Count == 2, "Native PPTX lost shape or image objects");
Check(reopenedSlides.Slides[0]?["notes"]?.ToString() == "Speaker notes", "Native PPTX lost speaker notes");
if (args.Contains("--write-samples")) { File.WriteAllBytes(Path.Combine(AppContext.BaseDirectory, "roundtrip.docx"), docx); File.WriteAllBytes(Path.Combine(AppContext.BaseDirectory, "roundtrip.xlsx"), xlsx); File.WriteAllBytes(Path.Combine(AppContext.BaseDirectory, "roundtrip.pptx"), pptx); }
var gallery = OfficeFile.Create("presentation"); var shapes = new JsonArray();
foreach (var kind in OfficeShapes.Paths.Keys) shapes.Add(new JsonObject { ["id"] = kind, ["kind"] = kind, ["x"] = 10, ["y"] = 20, ["width"] = 20, ["height"] = 30, ["color"] = "#107c41", ["stroke"] = "#c43e1c", ["strokeWidth"] = 3, ["rotation"] = 30 });
gallery.Slides[0]!["objects"] = shapes;
var reopenedGallery = OfficeInterchange.Import(OfficeInterchange.Export(gallery), ".pptx").Slides[0]!["objects"]!.AsArray();
foreach (var shape in shapes) { var matching = reopenedGallery.FirstOrDefault(o => o?["kind"]?.ToString() == shape?["kind"]?.ToString()); Check(matching is not null && matching["stroke"]?.ToString() == "#c43e1c" && SlideRenderer.Number(matching["strokeWidth"]) == 3 && SlideRenderer.Number(matching["rotation"]) == 30, "Shape geometry or formatting lost: " + shape?["kind"]); }
document.Data["layout"] = new JsonObject { ["pageSize"] = "letter", ["orientation"] = "landscape", ["columns"] = 3, ["columnGap"] = 8, ["customMargins"] = new JsonObject { ["top"] = 10, ["right"] = 15, ["bottom"] = 20, ["left"] = 25 } };
var reopenedLayout = OfficeInterchange.Import(OfficeInterchange.Export(document), ".docx").Data["layout"]!;
Check(reopenedLayout["pageSize"]?.ToString() == "letter" && reopenedLayout["orientation"]?.ToString() == "landscape" && SlideRenderer.Number(reopenedLayout["columns"]) == 3, "Native document page size, orientation or columns lost");
Check(Math.Abs(SlideRenderer.Number(reopenedLayout["customMargins"]?["left"]) - 25) < .03, "Custom margins lost");
var drawingDelta = new JsonArray(new JsonObject { ["insert"] = new JsonObject { ["gaius-drawing"] = new JsonObject { ["kind"] = "image", ["dataUrl"] = "data:image/png;base64," + Convert.ToBase64String(png), ["width"] = 260, ["height"] = 130 }.ToJsonString() } });
Check(RtfPipe.Rtf.ToHtml(RichTextInterop.ToRtf(drawingDelta)).Contains("data:image/png;base64,"), "Mobile drawing embed lost in native RTF conversion");
InkTests.Run(Check);
await InkTests.VerifyPdfRendering(Check);
LegacyWordTests.Run(Check);
HomeTemplateTests.Run(Check);
OpenDocumentTests.Run(Check);
await RasterFormatTests.Run(Check);
SheetFeatureChecks.Run(Check);
Console.WriteLine($"PASS: {checks} native rich-content, layout, drawing, workbook, formula, image and PDF assertions");
